35: function rpmLine(props: CadenceSensorSheetProps): string | null {
36:   if (props.uiState !== "connected") return null;
37:   if (props.crankRpm == null) return "페달을 돌려 센서를 확인하세요";
38:   const rpm = Math.max(0, Math.round(props.crankRpm));
39:   const kmh = Math.round(cadenceRpmToVirtualSpeedKmh(props.crankRpm));
40:   return `${rpm} rpm · 가상 ${kmh} km/h`;
41: }
