46:  * 주행 전에는 입력 준비(센서 연결·페달 확인 또는 체험 속도 선택)를 끝내는 표면이고,
47:  * 주행 중에는 단절 복구와 안전한 체험 입력 전환에만 쓴다.
48:  * TTS·BGM 같은 무관한 설정은 여기에 두지 않는다(주행 설정 시트가 계속 소유).
49:  */
50: export function CadenceSensorSheet(props: CadenceSensorSheetProps) {
51:   const { open, onClose } = props;
52: 
53:   useEffect(() => {
54:     if (!open) return;
55:     const onKey = (e: KeyboardEvent) => {
56:       if (e.key === "Escape") onClose();
57:     };
58:     window.addEventListener("keydown", onKey);
59:     return () => window.removeEventListener("keydown", onKey);
60:   }, [open, onClose]);
61: 
62:   if (!open) return null;
63: 
64:   const connected = props.uiState === "connected";
65:   const connecting = props.uiState === "connecting";
66:   const reconnecting = props.uiState === "disconnected";
